import { fireEvent, screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { renderWithProviders } from "../../../tests/utils";
import { ConversationEventType, type ConversationEvent } from "../../../types";
import { Event } from "./index";

function toolEvent(type: ConversationEventType, toolName: string): ConversationEvent {
  return {
    __typename: "ConversationEvent",
    id: "1",
    conversationEventType: type,
    name: toolName,
    actionText: "",
    flowId: "",
    slotValue: null,
    stepId: "",
    timestamp: new Date().toISOString(),
    originalTimestamp: 0,
    metadata: { parseData: {}, tool_name: toolName },
  };
}

describe("Event tool-run routing", () => {
  it("renders McpToolExecuted with CALM terminology", () => {
    renderWithProviders(
      <Event
        event={toolEvent(ConversationEventType.McpToolExecuted, "lock_card")}
        isSelected={false}
      />,
      { initialStoreState: { skillCatalog: {} } },
    );

    expect(screen.getByText("lock_card")).toBeInTheDocument();
    expect(screen.getByText(/used/)).toBeInTheDocument();
  });

  it("renders ToolExecuted with Mantle terminology", () => {
    renderWithProviders(
      <Event
        event={toolEvent(ConversationEventType.ToolExecuted, "lock_card")}
        isSelected={false}
      />,
      { initialStoreState: { skillCatalog: {} } },
    );

    expect(screen.getByText("lock_card")).toBeInTheDocument();
    expect(screen.getByText(/Tool call:/)).toBeInTheDocument();
  });
});

describe("Event selection for generic events", () => {
  it.each([ConversationEventType.UserInputSuppressed, ConversationEventType.UserSilenceTimeout])(
    "makes %s selectable",
    (conversationEventType) => {
      const onEventSelect = vi.fn();

      renderWithProviders(
        <Event
          event={toolEvent(conversationEventType, "event")}
          selectable
          onEventSelect={onEventSelect}
          isSelected={false}
        />,
      );

      fireEvent.click(screen.getByRole("button"));

      expect(onEventSelect).toHaveBeenCalledWith(
        expect.objectContaining({ conversationEventType }),
      );
    },
  );
});

describe("Event icons for voice events", () => {
  it.each([
    [ConversationEventType.UserInputSuppressed, "User input suppressed", "comment-xmark"],
    [ConversationEventType.UserSilenceTimeout, "User silence timeout", "ear"],
  ])("uses the %s event icon", (conversationEventType, label, icon) => {
    const { container } = renderWithProviders(
      <Event event={toolEvent(conversationEventType, "event")} isSelected={false} />,
    );

    expect(screen.getByText(label)).toBeInTheDocument();
    expect(container.querySelector(`svg[data-icon="${icon}"]`)).toBeInTheDocument();
  });
});

describe("Event memory routing", () => {
  it.each([
    [ConversationEventType.MemorySet, "set to"],
    [ConversationEventType.MemoryCleared, "cleared"],
  ])("renders %s as a memory row", (type, wording) => {
    renderWithProviders(
      <Event
        event={{
          ...toolEvent(type, "card_replace.replacement_reason"),
          value: type === ConversationEventType.MemorySet ? "stolen" : null,
        }}
        isSelected={false}
      />,
      { initialStoreState: { skillCatalog: {} } },
    );

    expect(screen.getByText("replacement_reason")).toBeInTheDocument();
    expect(screen.getByText(new RegExp(wording))).toBeInTheDocument();
  });
});

describe("Event ordered-block routing", () => {
  it.each([
    [ConversationEventType.OrderedBlockEntered, "entered"],
    [ConversationEventType.OrderedBlockCompleted, "completed"],
    [ConversationEventType.OrderedBlockCancelled, "cancelled"],
    [ConversationEventType.OrderedBlockInterrupted, "interrupted"],
    [ConversationEventType.OrderedBlockResumed, "resumed"],
  ])("renders %s as a block row", (type, verb) => {
    renderWithProviders(
      <Event
        event={{
          ...toolEvent(type, "submit"),
          skillId: "travel_notice",
          blockId: "submit",
        }}
        isSelected={false}
      />,
      { initialStoreState: { skillCatalog: {} } },
    );

    expect(screen.getByText("travel_notice")).toBeInTheDocument();
    expect(screen.getByText("submit")).toBeInTheDocument();
    expect(screen.getByText(new RegExp(`block ${verb}`))).toBeInTheDocument();
  });
});

describe("Event flow vs ordered-block copy", () => {
  it("paints Flow for compiled flow_completed and Block for ordered_block_completed", () => {
    renderWithProviders(
      <>
        <Event
          event={{
            ...toolEvent(ConversationEventType.FlowCompleted, "travel_notice__submit"),
            id: "flow-completed",
            flowId: "travel_notice__submit",
          }}
          isSelected={false}
        />
        <Event
          event={{
            ...toolEvent(ConversationEventType.OrderedBlockCompleted, "submit"),
            id: "block-completed",
            skillId: "travel_notice",
            blockId: "submit",
          }}
          isSelected={false}
        />
      </>,
      { initialStoreState: { skillCatalog: {} } },
    );

    expect(screen.getByText(/^Flow/)).toBeInTheDocument();
    expect(screen.getByText("travel_notice__submit")).toBeInTheDocument();
    expect(screen.getByText(/block completed/)).toBeInTheDocument();
    expect(screen.queryByText(/^Block/)).not.toBeInTheDocument();
  });
});
